function render(){
 if(dialog.open)dialog.close();
 pageId=location.hash.slice(1)||'chat';aux='';
 surface.innerHTML=renderPage(pageId);
 if(pageId==='tools'){surface.innerHTML=renderPage('capabilities');showDialog('工具管理','<div class="toolbar">'+search('搜索工具')+'</div><div class="list">'+[['读取文件','read_file · 读取明确指定的文件'],['写入文件','write_file · 写入实际内容'],['执行命令','bash · 通过原执行网关'],['图像理解','vision_analysis · 已配置服务']].map(x=>row(x[0],x[1],'',btn('查看','tool:'+x[0]),'box')).join('')+'</div>');}
 const match=PAGES.find(p=>p[0]===pageId);
 document.getElementById('preview-select').value=match?match[0]:'';
 document.title=(match?match[1]:'更多')+' · 忆涟千言 R3 原型';
 const active=['chat','home'].includes(pageId)?'chat':['workspace','workspaces','learning','outputs'].includes(pageId)?'workspaces':['capabilities','tools'].includes(pageId)?'capabilities':pageId.startsWith('settings')?'settings':pageId==='canvas'?'canvas':pageId==='account'?'account':'more';
 document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===active);if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 requestAnimationFrame(wireCanvas);
}
function wireCanvas(){
 document.querySelectorAll('.canvas').forEach(canvas=>{
  const svg=canvas.querySelector('svg.connections'),nodes=Array.from(canvas.querySelectorAll('.node'));
  if(!svg||!nodes.length)return;
  const area=canvas.getBoundingClientRect();
  const edges=pageId==='canvas'?[[0,1],[1,2],[2,3],[1,4],[4,5]]:pageId==='settings'?nodes.slice(1).map((_,i)=>[0,i+1]):[[0,1],...nodes.slice(2).map((_,i)=>[1,i+2])];
  svg.setAttribute('viewBox','0 0 '+area.width+' '+area.height);svg.setAttribute('preserveAspectRatio','none');
  svg.innerHTML=edges.map(([a,b])=>{
   const source=nodes[a].getBoundingClientRect(),dest=nodes[b].getBoundingClientRect();
   let x1,y1,x2,y2;
   if(pageId==='canvas'){x1=source.left+source.width/2-area.left;y1=source.bottom-area.top;x2=dest.left+dest.width/2-area.left;y2=dest.top-area.top;}
   else {const direction=dest.left>=source.left?1:-1;x1=(direction>0?source.right:source.left)-area.left;y1=source.top+source.height/2-area.top;x2=(direction>0?dest.left:dest.right)-area.left;y2=dest.top+dest.height/2-area.top;if(Math.abs(dest.left-source.left)<20){x1=source.left+source.width/2-area.left;x2=x1;y1=(dest.top>source.top?source.bottom:source.top)-area.top;y2=(dest.top>source.top?dest.top:dest.bottom)-area.top;}}
   const mid=pageId==='canvas'?(y1+y2)/2:(x1+x2)/2;
   const d=pageId==='canvas'?'M'+x1+' '+y1+' C'+x1+' '+mid+' '+x2+' '+mid+' '+x2+' '+y2:'M'+x1+' '+y1+' C'+mid+' '+y1+' '+mid+' '+y2+' '+x2+' '+y2;
   return '<path d="'+d+'" fill="none" stroke="#d2acd1" stroke-width="1.5"/>';
  }).join('');
 });
}
window.addEventListener('resize',()=>requestAnimationFrame(wireCanvas));
