 if(key==='tool'){showDialog(value,'<p>单项工具说明与参数。实际执行继续经过既有工具网关。</p><div class="code-area">'+(value==='写入文件'?'write_file\n\npath: 目标文件路径\ncontent: 待写入内容':'工具参数由真实注册表提供。')+'</div><p class="empty-note">这是说明预览，不会执行工具。</p>');return;}
